// ============================================================================
// FILE:     src/FileHarvester.Platform/Cloud/OAuth/OAuthStateStore.cs
// PURPOSE:  In-memory store for OAuth state nonces and their associated
//           PKCE code verifiers. The state nonce defends against CSRF;
//           the verifier proves the token exchange comes from the same
//           client. They are two separate values with two separate
//           owners: the state is generated by the application; the
//           verifier is generated by the OAuth SDK and handed back via
//           the out parameter of CreateAuthorizationCodeRequest.
// RELATION: Consumed by GoogleOAuthFlow (C.6.3) and by
//           OAuthLoopbackListener (C.6.2). Not persisted: a restart
//           invalidates in-flight flows, which is the correct behavior.
// ============================================================================

using System;
using System.Collections.Concurrent;
using System.Security.Cryptography;

namespace FileHarvester.Platform.Cloud.OAuth;

/// <summary>
/// In-memory store for OAuth state nonces and PKCE verifiers.
/// </summary>
/// <remarks>
/// <para>
/// Each entry is keyed by the state nonce. It carries the PKCE verifier
/// and the instant the entry was created. An entry is valid for a fixed
/// window (five minutes). On validation, the entry is removed before
/// the token exchange — a replay finds no entry and is rejected.
/// </para>
/// <para>
/// The store is thread-safe. It holds no I/O, no logging, no SDK
/// dependency. The clock is injectable for testability.
/// </para>
/// </remarks>
public sealed class OAuthStateStore
{
    /// <summary>
    /// The lifetime of a state entry. Fixed at five minutes. Named so a
    /// future change is a versioned decision, not a hidden edit.
    /// </summary>
    public static readonly TimeSpan EntryLifetime = TimeSpan.FromMinutes(5);

    private readonly ConcurrentDictionary<string, Entry> _entries = new(StringComparer.Ordinal);
    private readonly Func<DateTimeOffset> _now;

    /// <summary>
    /// Creates a store. The clock is optional; production uses UTC now.
    /// </summary>
    /// <param name="now">
    /// The clock. Null uses <c>DateTimeOffset.UtcNow</c>. Tests supply a
    /// fixed or advancing clock.
    /// </param>
    public OAuthStateStore(Func<DateTimeOffset>? now = null)
    {
        _now = now ?? (() => DateTimeOffset.UtcNow);
    }

    /// <summary>
    /// Generates a new state nonce. Thirty-two bytes from a cryptographic
    /// random source, Base64Url-encoded. This is the value the application
    /// sets on the authorization request URL and validates on the callback.
    /// </summary>
    /// <returns>A fresh state nonce. Never null or empty.</returns>
    public static string NewState()
    {
        var bytes = RandomNumberGenerator.GetBytes(32);
        return Base64UrlEncode(bytes);
    }

    /// <summary>
    /// Stores the PKCE verifier under the given state nonce. The state
    /// must not already exist.
    /// </summary>
    /// <param name="state">The state nonce. Non-null, non-empty.</param>
    /// <param name="codeVerifier">The PKCE verifier. Non-null, non-empty.</param>
    /// <exception cref="ArgumentException">
    /// The state or verifier is null or whitespace, or the state already
    /// has an unexpired entry.
    /// </exception>
    public void Store(string state, string codeVerifier)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);
        ArgumentException.ThrowIfNullOrWhiteSpace(codeVerifier);

        EvictExpired();

        var entry = new Entry(codeVerifier, _now());
        if (!_entries.TryAdd(state, entry))
        {
            throw new ArgumentException(
                "State already has an unexpired entry.",
                nameof(state));
        }
    }

    /// <summary>
    /// Validates the state and returns the associated PKCE verifier. The
    /// entry is removed before returning — one-time use. A second call
    /// with the same state throws.
    /// </summary>
    /// <param name="state">The state from the callback. Non-null, non-empty.</param>
    /// <returns>The PKCE verifier stored alongside the state.</returns>
    /// <exception cref="OAuthStateException">
    /// The state has no entry, or the entry has expired.
    /// </exception>
    public string Consume(string state)
    {
        ArgumentException.ThrowIfNullOrWhiteSpace(state);

        if (!_entries.TryRemove(state, out var entry))
        {
            throw new OAuthStateException("no entry for the returned state");
        }

        var age = _now() - entry.CreatedAt;
        if (age > EntryLifetime)
        {
            throw new OAuthStateException("state entry has expired");
        }

        return entry.CodeVerifier;
    }

    /// <summary>
    /// Removes every expired entry. Called opportunistically on Store.
    /// Never returns expired data to a caller.
    /// </summary>
    private void EvictExpired()
    {
        var now = _now();
        foreach (var kvp in _entries)
        {
            if (now - kvp.Value.CreatedAt > EntryLifetime)
            {
                _entries.TryRemove(kvp.Key, out _);
            }
        }
    }

    /// <summary>
    /// Base64Url encoding — the URL-safe alphabet, no padding. Matches the
    /// encoding the OAuth PKCE specification requires.
    /// </summary>
    private static string Base64UrlEncode(byte[] bytes)
    {
        var b64 = Convert.ToBase64String(bytes);
        return b64.TrimEnd((char)61).Replace((char)43, (char)45).Replace((char)47, (char)95);
    }

    /// <summary>
    /// A single state entry: the PKCE verifier and the creation instant.
    /// </summary>
    private sealed record Entry(string CodeVerifier, DateTimeOffset CreatedAt);
}
